fn clamp::(x, lo, hi) {
    if (x < lo) { return lo; }
    if (x > hi) { return hi; }
    return x;
}

fn sign::(x) {
    if (x > 0) { return 1; }
    if (x < 0) { return -1; }
    return 0;
}

fn lerp::(a, b, t) {
    return a + (b - a) * t;
}

fn dist::(x1, y1, x2, y2) {
    let dx = x2 - x1;
    let dy = y2 - y1;
    return @sqrt(dx * dx + dy * dy);
}

fn gcd::(a, b) {
    a = @abs(a); b = @abs(b);
    while (b != 0) {
        let t = b;
        b = a % b;
        a = t;
    }
    return a;
}

fn lcm::(a, b) {
    if (a == 0 || b == 0) { return 0; }
    return @abs(a * b) / gcd(a, b);
}

fn factorial::(n) {
    if (n < 0) { @throw "factorial: negative"; }
    let r = 1;
    let i = 2;
    while (i <= n) { r = r * i; i = i + 1; }
    return r;
}

fn fib::(n) {
    if (n < 2) { return n; }
    let a = 0; let b = 1; let i = 2;
    while (i <= n) {
        let t = a + b;
        a = b; b = t;
        i = i + 1;
    }
    return b;
}

fn is_prime::(n) {
    if (n < 2) { return false; }
    if (n % 2 == 0) { return n == 2; }
    let i = 3;
    while (i * i <= n) {
        if (n % i == 0) { return false; }
        i = i + 2;
    }
    return true;
}

fn primes_up_to::(n) {
    let out = [];
    let i = 2;
    while (i <= n) {
        if (is_prime(i)) { @push(out, i); }
        i = i + 1;
    }
    return out;
}

fn pow_mod::(base, exp, mod) {
    let r = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1) { r = (r * base) % mod; }
        exp = exp / 2;
        base = (base * base) % mod;
    }
    return r;
}

fn to_deg::(r) { return r * 180.0 / 3.141592653589793; }
fn to_rad::(d) { return d * 3.141592653589793 / 180.0; }

fn avg::(xs) {
    if (@len(xs) == 0) { return 0; }
    let s = 0;
    for x in xs { s = s + x; }
    return s / @len(xs);
}

fn median::(xs) {
    if (@len(xs) == 0) { return 0; }
    let copy = xs;
    @sort(copy);
    let n = @len(copy);
    if (n % 2 == 1) { return copy[n / 2]; }
    return (copy[n / 2 - 1] + copy[n / 2]) / 2;
}

fn stddev::(xs) {
    if (@len(xs) < 2) { return 0; }
    let m = avg(xs);
    let s = 0;
    for x in xs {
        let d = x - m;
        s = s + d * d;
    }
    return @sqrt(s / @len(xs));
}
